/// The C++ enumeration `datamunge::algebra::MonomialOrder`.
///
/// A newtype over the C++ value, with an associated constant per enumerator: other values pass through unchanged. `Display` writes the C++ enumerator name (or the number).
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct MonomialOrder(pub i64);

impl MonomialOrder {
    /// C++ `datamunge::algebra::MonomialOrder::Lex` (0).
    pub const LEX: MonomialOrder = MonomialOrder(0);
    /// C++ `datamunge::algebra::MonomialOrder::Grlex` (1).
    pub const GRLEX: MonomialOrder = MonomialOrder(1);
    /// C++ `datamunge::algebra::MonomialOrder::Grevlex` (2).
    pub const GREVLEX: MonomialOrder = MonomialOrder(2);
}

