    ///
    /// Returns this plot, for chaining.
    ///
    /// See also `set_title()`.
    pub fn title(&self, value: &str) -> Result<RPlot> {
        let mut rc = rosetta::Call::new(548);
        rc.arg(self);
        rc.arg(&value);
        rc.run()?.value()
    }

