pub trait RHSImpl: std::any::Any + Send + Sync {
    /// C++ `datamunge::ode::RHS::evaluate` (pure virtual: the default fails). The default runs the C++ implementation.
    fn evaluate(&self, this: &RHS, t: f64, y: Vec<f64>) -> Result<Vec<f64>> {
        this.evaluate(t, &y)
    }
}

