    /// # Errors
    ///
    /// - [`ErrorKind::InvalidArgument`] (C++ `std::invalid_argument`): For invalid data or basis size.
    /// - [`ErrorKind::Native`] (C++ `std::runtime_error`): If all candidate systems fail numerically.
    ///
    /// See also `gcv()` and `smoothing_path()`.
    pub fn new(x: &[f64], y: &[f64], n_basis: usize) -> Result<PSplineRegression> {
        let mut rc = rosetta::Call::constructor(2379, None);
        rc.arg(&x);
        rc.arg(&y);
        rc.arg(&n_basis);
        rc.construct().map(<PSplineRegression as rosetta::Class>::from_handle)
    }

    /// `n_basis` B-splines of the given `degree` with equally spaced knots over the range of
