/// An owned B-rep solid with value-returning modelling and export operations.
/// Geometry uses doubles in caller-selected consistent units. Copies own topology;
/// immutable surfaces may be shared. Operations return new solids, preserving inputs.
/// Unsupported kernel operations throw std::runtime_error with the kernel diagnostic.
/// Concurrent const access is safe; do not mutate a shared object concurrently.
///
/// Wraps the C++ class `datamunge::cad::Solid`.
///
/// # Example
///
/// ```text
/// auto block = dm::cad::Solid::box(4, 3, 2);
/// auto hole = dm::cad::Solid::cylinder(.4, 4).translated(2, 1.5, -1);
/// auto part = block.subtracted(hole);
/// part.save("part.step");
/// ```
///
/// Cloning shares the C++ object. Dropping the last clone releases it (or `close` does at once); [`cast`] converts to a derived class.
///
/// See also `Model`, `FeatureTree` and `load_scene()`.
#[derive(Clone)]
pub struct CadSolid {
    h: Arc<rosetta::Handle>,
    direct: bool,
}

impl rosetta::Class for CadSolid {
    const CLASS: u32 = 278;
    fn from_handle(handle: Arc<rosetta::Handle>) -> Self {
        CadSolid { h: handle, direct: false }
    }
    fn handle(&self) -> &Arc<rosetta::Handle> {
        &self.h
    }
    fn is_direct(&self) -> bool {
        self.direct
    }
    fn set_direct(&mut self) {
        self.direct = true;
    }
}

impl rosetta::Encode for CadSolid {
    fn encode(&self, w: &mut rosetta::Writer) -> Result<()> {
        rosetta::encode_object(w, rosetta::Class::handle(self))
    }
    fn object_handle(&self) -> Option<&Arc<rosetta::Handle>> {
        Some(rosetta::Class::handle(self))
    }
}

