/// A small code-driven scene facade, exposed as CadScene in Python/R.
/// Owns scene/camera/render controls. All operations delegate to the canonical
/// CAD, polygon and renderer APIs; copying retains independent scene state.
///
/// Wraps the C++ class `datamunge::cad::View`.
///
/// # Example
///
/// ```text
/// dm::cad::View view;
/// view.add(dm::cad::Solid::box(2, 3, 4), "#3b82f6", "block");
/// view.size(640, 480); view.render("block.png");
/// ```
///
/// Cloning shares the C++ object. Dropping the last clone releases it (or `close` does at once); [`cast`] converts to a derived class.
#[derive(Clone)]
pub struct CadScene {
    h: Arc<rosetta::Handle>,
    direct: bool,
}

impl rosetta::Class for CadScene {
    const CLASS: u32 = 279;
    fn from_handle(handle: Arc<rosetta::Handle>) -> Self {
        CadScene { h: handle, direct: false }
    }
    fn handle(&self) -> &Arc<rosetta::Handle> {
        &self.h
    }
    fn is_direct(&self) -> bool {
        self.direct
    }
    fn set_direct(&mut self) {
        self.direct = true;
    }
}

impl rosetta::Encode for CadScene {
    fn encode(&self, w: &mut rosetta::Writer) -> Result<()> {
        rosetta::encode_object(w, rosetta::Class::handle(self))
    }
    fn object_handle(&self) -> Option<&Arc<rosetta::Handle>> {
        Some(rosetta::Class::handle(self))
    }
}

impl rosetta::FromValue for CadScene {
    fn from_value(value: Value) -> Result<Self> {
        rosetta::object_from(value, "CadScene")
    }
}

impl std::fmt::Debug for CadScene {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        rosetta::describe(f, "CadScene", rosetta::Class::handle(self))
    }
}

