/// each split into two counterclockwise triangles, for a total of nx*ny*2 triangles and
/// (nx+1)*(ny+1) nodes, ordered row-major (x fastest, then y).
/// Throws std::invalid_argument if nx or ny is 0, or if x1 \<= x0 or y1 \<= y0.
///
/// Calls C++ `datamunge::fem::make_rectangular_mesh2d`.
pub fn make_rectangular_mesh2d(x0: f64, y0: f64, x1: f64, y1: f64, nx: usize, ny: usize) -> Result<Mesh2D> {
    let mut rc = rosetta::Call::new(125);
    rc.arg(&x0);
    rc.arg(&y0);
    rc.arg(&x1);
    rc.arg(&y1);
    rc.arg(&nx);
    rc.arg(&ny);
    rc.run()?.value()
}

