/// - [`ErrorKind::LengthError`] (C++ `std::length_error`): Work/container size exhaustion.
///
/// See also `convex_hull_analyze()`, `convex_hull_trace()` and `orientation_sign()`.
pub fn convex_hull(points: &[Point2D]) -> Result<Vec<Point2D>> {
    let mut rc = rosetta::Call::new(130);
    rc.arg(&points);
    rc.run()?.value()
}

