/// Returns true when a finite approximate unique intersection was constructed.
///
/// # Errors
///
/// - [`ErrorKind::InvalidArgument`] (C++ `std::invalid_argument`): Nonfinite coordinate.
/// - [`ErrorKind::ArithmeticError`] (C++ `std::overflow_error`): Nonzero quotient or final coordinate exceeds finite represented range.
///
/// See also `segment_intersection_point()`.
pub fn line_intersection_point(p1: &Point2D, p2: &Point2D, p3: &Point2D, p4: &Point2D, out: &Point2D) -> Result<bool> {
    let mut rc = rosetta::Call::new(156);
    rc.arg(&p1);
    rc.arg(&p2);
    rc.arg(&p3);
    rc.arg(&p4);
    rc.arg(&out);
    rc.run()?.value()
}

