/// See also `bartlett_test()` and `fligner_killeen_test()`.
pub fn levene_test(values: &[f64], group_sizes: &[usize]) -> Result<HypothesisTestResult> {
    let mut rc = rosetta::Call::new(197);
    rc.arg(&values);
    rc.arg(&group_sizes);
    rc.run()?.value()
}

