///
/// # Errors
///
/// - [`ErrorKind::InvalidArgument`] (C++ `std::invalid_argument`): Invalid groups, nonfinite input or all observations tied.
///
/// See also [`HypothesisTestResult`].
pub fn kruskal_wallis_test(values: &[f64], group_sizes: &[usize]) -> Result<HypothesisTestResult> {
    let mut rc = rosetta::Call::new(200);
    rc.arg(&values);
    rc.arg(&group_sizes);
    rc.run()?.value()
}

